import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Activity, AlarmClock, ArrowDownRight, ArrowRight, AudioLines, Bell, CalendarDays,
  Check, CheckCheck, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, Circle,
  Clock3, CloudRain, Command, Download, Flame, Focus, Headphones, Home, Lightbulb,
  ListTodo, Menu, Moon, MoonStar, MoreHorizontal, NotebookPen, Pause, Play, Plus,
  Search, Settings2, SlidersHorizontal, Sparkles, Sun, Target, Timer, Trash2, Trees,
  Volume2, VolumeX, Waves, Wind, X, Zap, type LucideIcon
} from 'lucide-react';

type Page = 'Home' | 'Tasks' | 'Planner' | 'Ideas' | 'Focus' | 'Sleep Studio' | 'Insights' | 'Settings';
type Task = { id: string; title: string; done: boolean; priority: 'Low'|'Normal'|'High'; due: string; list: string; created: number };
type Note = { id: string; title: string; body: string; tag: string; updated: number };
type SoundKey = 'rain'|'thunder'|'fire'|'forest'|'ocean'|'noise';
type SoundState = Record<SoundKey, number>;
type Prefs = {
  name: string; theme: 'dark'|'light'; accent: string; greeting: boolean; boot: boolean; motion: boolean;
  clock24: boolean; weekStartsMonday: boolean; compact: boolean; soundMaster: number; timerMinutes: number;
  fadeMinutes: number; defaultPage: Page; showProgress: boolean; showClock: boolean; showQuote: boolean;
};

const STORAGE = 'dayflow-v1';
const pages: {name:Page; icon:LucideIcon; section:string}[] = [
  {name:'Home',icon:Home,section:'Workspace'}, {name:'Tasks',icon:ListTodo,section:'Workspace'},
  {name:'Planner',icon:CalendarDays,section:'Workspace'}, {name:'Ideas',icon:NotebookPen,section:'Workspace'},
  {name:'Focus',icon:Target,section:'Personal'}, {name:'Sleep Studio',icon:MoonStar,section:'Personal'},
  {name:'Insights',icon:Activity,section:'Personal'}, {name:'Settings',icon:Settings2,section:'System'}
];
const initialTasks: Task[] = [
  {id:'t1',title:'Plan the week and set priorities',done:false,priority:'High',due:todayISO(),list:'Personal',created:Date.now()},
  {id:'t2',title:'Work on the Dayflow project',done:false,priority:'High',due:todayISO(),list:'Projects',created:Date.now()},
  {id:'t3',title:'Review notes and capture new ideas',done:true,priority:'Normal',due:todayISO(),list:'Personal',created:Date.now()},
  {id:'t4',title:'Take a proper break',done:false,priority:'Low',due:todayISO(),list:'Wellbeing',created:Date.now()},
  {id:'t5',title:'Prepare tomorrow’s plan',done:false,priority:'Normal',due:todayISO(),list:'Personal',created:Date.now()},
];
const defaultPrefs: Prefs = {
  name:'there',theme:'light',accent:'#7c6cff',greeting:true,boot:true,motion:true,clock24:false,
  weekStartsMonday:true,compact:false,soundMaster:70,timerMinutes:30,fadeMinutes:5,defaultPage:'Home',
  showProgress:true,showClock:true,showQuote:true
};
const defaultSounds: SoundState = {rain:58,thunder:14,fire:24,forest:0,ocean:0,noise:0};

function todayISO(){ const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function isoOf(d:Date){ return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function uid(){ return Math.random().toString(36).slice(2,10); }
function load<T,>(key:string, fallback:T):T {
  try { const x=localStorage.getItem(key); return x ? {...fallback,...JSON.parse(x)} : fallback; } catch { return fallback; }
}
function save(key:string, value:unknown){ try { localStorage.setItem(key,JSON.stringify(value)); } catch(e){ console.warn('Could not save Dayflow data',e); } }
function dateLabel(date=new Date()){ return new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(date); }
function greet(){const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':h<21?'Good evening':'It’s late';}
function formatTime(sec:number){const s=Math.max(0,Math.floor(sec));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}

export default function App(){
  const [prefs,setPrefs] = useState<Prefs>(()=>load('dayflow-prefs',defaultPrefs));
  const [tasks,setTasks] = useState<Task[]>(()=>{try{return JSON.parse(localStorage.getItem('dayflow-tasks')||'null')||initialTasks;}catch{return initialTasks;}});
  const [notes,setNotes] = useState<Note[]>(()=>{try{return JSON.parse(localStorage.getItem('dayflow-notes')||'null')||[{id:'n1',title:'Ideas for Dayflow',body:'A calm, premium workspace for planning, focus, and rest.\\n\\n• Custom themes\\n• Ambient sound mixer\\n• Daily review',tag:'Product',updated:Date.now()}];}catch{return [];}});
  const [page,setPage] = useState<Page>(prefs.defaultPage || 'Home');
  const [booting,setBooting] = useState(()=>prefs.boot && !sessionStorage.getItem('dayflow-booted'));
  const [now,setNow] = useState(new Date());
  const [showAdd,setShowAdd] = useState(false);
  const [taskTitle,setTaskTitle] = useState('');
  const [taskList,setTaskList] = useState('Personal');
  const [taskPriority,setTaskPriority] = useState<Task['priority']>('Normal');
  const [filter,setFilter] = useState<'All'|'Open'|'Completed'>('All');
  const [search,setSearch] = useState('');
  const [toast,setToast] = useState('');
  const [sidebarOpen,setSidebarOpen] = useState(false);
  const [commandOpen,setCommandOpen] = useState(false);
  const [notesSearch,setNotesSearch] = useState('');
  const [editingNote,setEditingNote] = useState<Note|null>(null);
  const [sounds,setSounds] = useState<SoundState>(()=>load('dayflow-sounds',defaultSounds));
  const [activeSounds,setActiveSounds] = useState<SoundKey[]>([]);
  const [isPlaying,setIsPlaying] = useState(false);
  const [timerRemaining,setTimerRemaining] = useState(0);
  const [timerRunning,setTimerRunning] = useState(false);
  const [focusSeconds,setFocusSeconds] = useState(25*60);
  const [focusRunning,setFocusRunning] = useState(false);
  const [focusLength,setFocusLength] = useState(25);
  const [soundPreset,setSoundPreset] = useState<Record<string,SoundState>>(()=>load('dayflow-presets',{}));
  const audioRef = useRef<AudioContext|null>(null);
  const nodesRef = useRef<Partial<Record<SoundKey,{source:AudioBufferSourceNode; gain:GainNode}>>>({});
  const masterRef = useRef<GainNode|null>(null);
  const soundTimerRef = useRef<number|null>(null);
  const toastRef = useRef<number|null>(null);

  useEffect(()=>{save('dayflow-prefs',prefs);document.documentElement.dataset.theme=prefs.theme;document.documentElement.style.setProperty('--accent',prefs.accent);document.documentElement.dataset.motion=prefs.motion?'on':'off';document.documentElement.dataset.compact=prefs.compact?'on':'off';},[prefs]);
  useEffect(()=>save('dayflow-tasks',tasks),[tasks]);
  useEffect(()=>save('dayflow-notes',notes),[notes]);
  useEffect(()=>save('dayflow-sounds',sounds),[sounds]);
  useEffect(()=>save('dayflow-presets',soundPreset),[soundPreset]);
  useEffect(()=>{const t=window.setInterval(()=>setNow(new Date()),1000);return()=>clearInterval(t);},[]);
  useEffect(()=>{if(booting){const t=window.setTimeout(()=>{setBooting(false);sessionStorage.setItem('dayflow-booted','1');},1700);return()=>clearTimeout(t);}},[booting]);
  useEffect(()=>{if(!toast)return; if(toastRef.current)clearTimeout(toastRef.current);toastRef.current=window.setTimeout(()=>setToast(''),2600);return()=>{if(toastRef.current)clearTimeout(toastRef.current);};},[toast]);
  useEffect(()=>{if(!timerRunning)return;const id=window.setInterval(()=>setTimerRemaining(s=>{if(s<=1){setTimerRunning(false);setIsPlaying(false);stopAudio();setToast('Sleep timer finished. Rest well.');return 0;}return s-1;}),1000);return()=>clearInterval(id);},[timerRunning]);
  useEffect(()=>{if(!focusRunning)return;const id=window.setInterval(()=>setFocusSeconds(s=>{if(s<=1){setFocusRunning(false);setToast('Focus session complete. Take a short break.');return focusLength*60;}return s-1;}),1000);return()=>clearInterval(id);},[focusRunning,focusLength]);
  useEffect(()=>{if(!audioRef.current||!masterRef.current)return;const fadeSeconds=prefs.fadeMinutes*60;if(timerRunning&&fadeSeconds>0&&timerRemaining<=fadeSeconds){const factor=Math.max(0,timerRemaining/fadeSeconds);masterRef.current.gain.setTargetAtTime((prefs.soundMaster/100)*factor,audioRef.current.currentTime,0.15);}else{masterRef.current.gain.setTargetAtTime(prefs.soundMaster/100,audioRef.current.currentTime,0.15);}},[timerRemaining,timerRunning,prefs.fadeMinutes,prefs.soundMaster]);
  useEffect(()=>()=>{stopAudio();},[]);

  const notify=useCallback((s:string)=>setToast(s),[]);
  const doneCount=tasks.filter(t=>t.done).length;
  const progress=tasks.length?Math.round(doneCount/tasks.length*100):0;
  const todaysTasks=tasks.filter(t=>t.due===todayISO());
  const visibleTasks=useMemo(()=>tasks.filter(t=>(filter==='All'||(filter==='Open'?!t.done:t.done))&&(`${t.title} ${t.list}`.toLowerCase().includes(search.toLowerCase()))),[tasks,filter,search]);
  const setPref=<K extends keyof Prefs>(key:K,value:Prefs[K])=>setPrefs(p=>({...p,[key]:value}));
  function addTask(e?:React.FormEvent){e?.preventDefault();const title=taskTitle.trim();if(!title)return;setTasks(t=>[{id:uid(),title,done:false,priority:taskPriority,due:todayISO(),list:taskList,created:Date.now()},...t]);setTaskTitle('');setShowAdd(false);notify('Task added to your list');}
  function toggleTask(id:string){setTasks(ts=>ts.map(t=>t.id===id?{...t,done:!t.done}:t));}
  function deleteTask(id:string){setTasks(ts=>ts.filter(t=>t.id!==id));notify('Task deleted');}
  function changePage(p:Page){setPage(p);setSidebarOpen(false);setCommandOpen(false);}
  function exportData(){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),prefs,tasks,notes,sounds,soundPreset},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='dayflow-backup.json';a.click();URL.revokeObjectURL(url);notify('Backup exported');}
  function importData(e:React.ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const d=JSON.parse(String(reader.result));if(d.prefs)setPrefs(p=>({...p,...d.prefs}));if(Array.isArray(d.tasks))setTasks(d.tasks);if(Array.isArray(d.notes))setNotes(d.notes);if(d.sounds)setSounds(s=>({...s,...d.sounds}));if(d.soundPreset)setSoundPreset(d.soundPreset);notify('Backup imported successfully');}catch{notify('That backup file could not be read');}};reader.readAsText(file);e.target.value='';}
  function makeAudio(){if(!audioRef.current){const Ctx=window.AudioContext||(window as any).webkitAudioContext;if(!Ctx){notify('Audio playback is not supported in this browser');return null;}audioRef.current=new Ctx();masterRef.current=audioRef.current.createGain();masterRef.current.gain.value=prefs.soundMaster/100;masterRef.current.connect(audioRef.current.destination);}if(audioRef.current.state==='suspended')void audioRef.current.resume();return audioRef.current;}
  function createNoiseBuffer(ctx:AudioContext,kind:SoundKey){const length=ctx.sampleRate*8;const buffer=ctx.createBuffer(1,length,ctx.sampleRate);const data=buffer.getChannelData(0);let last=0;for(let i=0;i<length;i++){const white=Math.random()*2-1;if(kind==='noise')data[i]=white;else if(kind==='ocean'){last=0.97*last+0.03*white;data[i]=last*3;}else if(kind==='thunder'){last=0.985*last+0.015*white;data[i]=last*2.5;}else if(kind==='rain'){last=0.2*last+0.8*white;data[i]=last*0.7;}else if(kind==='forest'){last=0.95*last+0.05*white;data[i]=last*1.7;}else{last=0.65*last+0.35*white;data[i]=last*0.5;}}return buffer;}
  function startSound(key:SoundKey){const ctx=makeAudio();if(!ctx||nodesRef.current[key])return;const source=ctx.createBufferSource();source.buffer=createNoiseBuffer(ctx,key);source.loop=true;const gain=ctx.createGain();gain.gain.value=sounds[key]/100;source.connect(gain);gain.connect(masterRef.current!);source.start();nodesRef.current[key]={source,gain};setActiveSounds(s=>s.includes(key)?s:[...s,key]);setIsPlaying(true);}
  function stopSound(key:SoundKey){const node=nodesRef.current[key];if(node){try{node.source.stop();}catch{}node.source.disconnect();node.gain.disconnect();delete nodesRef.current[key];}setActiveSounds(s=>s.filter(k=>k!==key));}
  function stopAudio(){(Object.keys(nodesRef.current) as SoundKey[]).forEach(stopSound);setIsPlaying(false);}
  function toggleSound(key:SoundKey){if(nodesRef.current[key])stopSound(key);else startSound(key);}
  function updateSound(key:SoundKey,value:number){setSounds(s=>({...s,[key]:value}));const node=nodesRef.current[key];if(node&&audioRef.current)node.gain.gain.setTargetAtTime(value/100,audioRef.current.currentTime,0.08);}
  function setMaster(value:number){setPref('soundMaster',value);if(masterRef.current&&audioRef.current)masterRef.current.gain.setTargetAtTime(value/100,audioRef.current.currentTime,0.08);}
  function playMix(){const enabled=(Object.keys(sounds) as SoundKey[]).filter(k=>sounds[k]>0);if(!enabled.length){notify('Increase a sound level first');return;}const ctx=makeAudio();if(!ctx)return;enabled.forEach(k=>{if(!nodesRef.current[k])startSound(k);});setIsPlaying(true);}
  function setTimer(){setTimerRemaining(prefs.timerMinutes*60);setTimerRunning(true);if(!isPlaying)playMix();notify(`Sleep timer set for ${prefs.timerMinutes} minutes`);}
  function savePreset(){const name=window.prompt('Name this sound mix','My sleep mix');if(name?.trim()){setSoundPreset(p=>({...p,[name.trim()]:sounds}));notify('Sound mix saved');}}
  function loadPreset(name:string){setSounds(soundPreset[name]);Object.entries(soundPreset[name]).forEach(([k,v])=>{const key=k as SoundKey;const node=nodesRef.current[key];if(node&&audioRef.current)node.gain.gain.setTargetAtTime((v as number)/100,audioRef.current.currentTime,0.08);});notify(`Loaded ${name}`);}
  useEffect(()=>{const fn=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setCommandOpen(v=>!v);}if(e.key==='Escape'){setCommandOpen(false);setShowAdd(false);setSidebarOpen(false);}if(e.key.toLowerCase()==='n'&&!['INPUT','TEXTAREA'].includes((e.target as HTMLElement)?.tagName)){e.preventDefault();setShowAdd(true);}};window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn);},[]);
  const iconForSound:Record<SoundKey,LucideIcon>={rain:CloudRain,thunder:Zap,fire:Flame,forest:Trees,ocean:Waves,noise:Wind};
  const soundNames:Record<SoundKey,string>={rain:'Rain on a window',thunder:'Distant thunder',fire:'Fireplace',forest:'Night forest',ocean:'Ocean waves',noise:'Soft noise'};
  const activePage=pages.find(p=>p.name===page)||pages[0];

  if(booting)return <div className="boot-screen"><div className="boot-orbit"><div className="boot-core"><Activity size={34}/></div><i/><i/><i/></div><div className="boot-wordmark">dayflow<span>.</span></div><div className="boot-tagline">Plan your day. Find your flow.</div><div className="boot-progress"><span/></div><button className="boot-skip" onClick={()=>{setBooting(false);sessionStorage.setItem('dayflow-booted','1');}}>Skip intro</button></div>;

  return <div className={`app-shell ${sidebarOpen?'sidebar-open':''}`}>
    <div className="bg-blobs" aria-hidden="true"><i/><i/><i/></div>
    <aside className="sidebar">
      <button className="brand" onClick={()=>changePage('Home')}><span className="brand-mark"><Activity size={21}/></span><span className="brand-name">dayflow<span>.</span><small>Your personal space</small></span></button>
      <button className="workspace-switch"><span className="workspace-avatar">D</span><span><b>My workspace</b><small>Personal space</small></span><ChevronDown size={15}/></button>
      {['Workspace','Personal','System'].map(section=><div className="nav-section" key={section}><div className="nav-label">{section}</div>{pages.filter(p=>p.section===section).map(item=><button key={item.name} className={`nav-link ${page===item.name?'active':''}`} onClick={()=>changePage(item.name)}><item.icon size={18}/><span>{item.name}</span>{item.name==='Tasks'&&<span className="nav-count">{tasks.filter(t=>!t.done).length}</span>}{item.name==='Sleep Studio'&&isPlaying&&<span className="playing-dot"/>}</button>)}</div>)}
      <div className="sidebar-bottom">{prefs.showQuote&&<div className="sidebar-quote"><Sparkles size={15}/><p>Small steps, every day.</p><span>Your pace is enough.</span></div>}<button className="profile-row" onClick={()=>changePage('Settings')}><div className="profile-avatar">{(prefs.name||'D').slice(0,1).toUpperCase()}</div><span><b>{prefs.name==='there'?'Your profile':prefs.name}</b><small>Personal account</small></span><MoreHorizontal size={17}/></button></div>
    </aside>
    {sidebarOpen&&<button className="mobile-scrim" aria-label="Close navigation" onClick={()=>setSidebarOpen(false)}/>}
    <main className="main-area">
      <header className="topbar"><div className="topbar-left"><button className="icon-button mobile-menu" aria-label="Open menu" onClick={()=>setSidebarOpen(true)}><Menu size={19}/></button><div className="breadcrumb">Workspace <ChevronRight size={14}/><span>{page}</span></div></div><div className="topbar-actions"><button className="search-trigger" onClick={()=>setCommandOpen(true)}><Search size={16}/><span>Search anything...</span><kbd>⌘ K</kbd></button><button className="icon-button" title="Quick add task" onClick={()=>setShowAdd(true)}><Plus size={19}/></button><button className="icon-button" title="Settings" onClick={()=>changePage('Settings')}><SlidersHorizontal size={18}/></button><div className="top-date">{now.toLocaleDateString(undefined,{month:'short',day:'numeric'})}</div></div></header>
      <div className="page-content">
        {page==='Home'&&<section className="page-enter">
          <div className="hero-row"><div><div className="eyebrow"><span className="status-dot"/>{dateLabel(now)}</div><h1>{prefs.greeting?`${greet()}, ${prefs.name==='there'?'there':prefs.name}.`:'Welcome back.'}</h1><p className="hero-subtitle">A little clarity goes a long way. Here's your space today.</p></div><div className="hero-clock">{prefs.showClock&&<><span>{now.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',hour12:!prefs.clock24})}</span><small>{now.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</small></>}</div></div>
          <div className="overview-grid">{([{n:todaysTasks.filter(t=>!t.done).length,l:'Due today',tone:'lilac',go:'Tasks'},{n:tasks.filter(t=>!t.done).length,l:'Open tasks',tone:'peach',go:'Tasks'},{n:doneCount,l:'Completed',tone:'mint',go:'Insights'},{n:notes.length,l:'Ideas saved',tone:'sky',go:'Ideas'}] as {n:number;l:string;tone:string;go:Page}[]).map(o=><button key={o.l} className={`ov-tile ov-${o.tone}`} onClick={()=>changePage(o.go)}><svg className="wave" viewBox="0 0 64 28" aria-hidden="true"><path d="M2 16C10 2 14 26 22 14s12-12 18 0 14 10 22-6"/></svg><b>{o.n}</b><span>{o.l}</span></button>)}</div>
          <div className="home-grid">
            {prefs.showProgress&&<div className="panel progress-panel"><div className="panel-head"><div><div className="panel-kicker">Your day at a glance</div><h3>Daily progress</h3></div><span className="icon-chip"><Target size={17}/></span></div><div className="progress-content"><div className="progress-ring" style={{'--progress':`${progress*3.6}deg`} as React.CSSProperties}><div><b>{progress}%</b><small>completed</small></div></div><div className="progress-stats"><div><span className="stat-bullet green"/><span>Completed</span><b>{doneCount}</b></div><div><span className="stat-bullet muted"/><span>Remaining</span><b>{tasks.length-doneCount}</b></div><div><span className="stat-bullet purple"/><span>Due today</span><b>{todaysTasks.length}</b></div></div></div><div className="panel-foot"><span>{progress===100?'Everything checked off. Beautiful work.':'Every completed task is progress.'}</span><ArrowRight size={15}/></div></div>}
            <div className="panel focus-card"><div className="focus-card-top"><span className="icon-chip"><Focus size={17}/></span><span className="live-label"><span className="status-dot"/> READY WHEN YOU ARE</span></div><div className="focus-card-title"><h3>Make room for focus.</h3><p>One thing at a time. Give your attention somewhere to land.</p></div><div className="focus-card-bottom"><div className="focus-mini-time"><Timer size={16}/><span>{focusLength} min session</span></div><button className="button-primary small" onClick={()=>{changePage('Focus');setFocusRunning(true);}}>Start focus <ArrowRight size={15}/></button></div><div className="focus-orb orb-one"/><div className="focus-orb orb-two"/></div>
          </div>
          <div className="week-strip" role="list">{Array.from({length:7},(_,i)=>{const d=new Date(now);d.setDate(d.getDate()-((d.getDay()+6)%7)+i);const iso=isoOf(d);return <button key={iso} role="listitem" className={`strip-day ${iso===todayISO()?'today':''}`} onClick={()=>changePage('Planner')}><small>{d.toLocaleDateString(undefined,{weekday:'short'})}</small><b>{d.getDate()}</b><i className={tasks.some(t=>t.due===iso&&!t.done)?'on':''}/></button>;})}</div>
          <div className="section-heading"><div><div className="panel-kicker">Keep your momentum</div><h2>Today's tasks <span className="heading-count">{todaysTasks.filter(t=>!t.done).length}</span></h2></div><button className="text-button" onClick={()=>changePage('Tasks')}>View all tasks <ArrowRight size={15}/></button></div>
          <div className="panel task-panel">{todaysTasks.slice(0,5).map(t=><TaskRow key={t.id} task={t} onToggle={toggleTask} onDelete={deleteTask}/>)}{todaysTasks.length===0&&<EmptyState title="A little breathing room." text="Add a task when you're ready." action="Add a task" onClick={()=>setShowAdd(true)}/>}<button className="add-inline" onClick={()=>setShowAdd(true)}><Plus size={16}/> Add a task for today <kbd>N</kbd></button></div>
          <div className="bottom-grid"><div className="panel idea-card"><div className="panel-head"><div><div className="panel-kicker">Capture the thought</div><h3>Ideas don't wait.</h3></div><span className="icon-chip violet"><Lightbulb size={17}/></span></div><p>Give your next thought somewhere to live. You can turn it into a task whenever you're ready.</p><button className="button-secondary" onClick={()=>{setEditingNote(null);changePage('Ideas');}}>Open idea studio <ArrowRight size={15}/></button></div><div className="panel sleep-card"><div className="sleep-card-art"><MoonStar size={34}/><span className="star star-a">✦</span><span className="star star-b">·</span><span className="star star-c">✧</span></div><div className="sleep-card-copy"><div className="panel-kicker">When it's time to unwind</div><h3>Find your quiet.</h3><p>Build a soundscape that feels like yours.</p><button className="button-secondary" onClick={()=>changePage('Sleep Studio')}>Visit sleep studio <ArrowRight size={15}/></button></div></div></div>
        </section>}

        {page==='Tasks'&&<section className="page-enter"><PageTitle kicker="Make space for what matters" title="Your tasks." subtitle="Get it out of your head and into a plan." action={<button className="button-primary" onClick={()=>setShowAdd(true)}><Plus size={17}/> New task</button>}/><div className="task-toolbar"><div className="segmented">{(['All','Open','Completed'] as const).map(f=><button key={f} className={filter===f?'selected':''} onClick={()=>setFilter(f)}>{f}{f==='All'&&<span>{tasks.length}</span>}</button>)}</div><div className="input-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Find a task..."/></div></div><div className="panel task-panel full-task-list">{visibleTasks.map(t=><TaskRow key={t.id} task={t} onToggle={toggleTask} onDelete={deleteTask}/>)}{visibleTasks.length===0&&<EmptyState title="Nothing here just yet." text="Try another filter or add a new task." action="Create task" onClick={()=>setShowAdd(true)}/>}</div><div className="list-footer"><span>{tasks.filter(t=>!t.done).length} tasks to go at your own pace</span><span>Press <kbd>N</kbd> to add a task</span></div></section>}

        {page==='Planner'&&<Planner tasks={tasks} onToggle={toggleTask} onDelete={deleteTask} onAdd={()=>setShowAdd(true)} now={now}/>}
        {page==='Ideas'&&<section className="page-enter"><PageTitle kicker="A home for your thoughts" title="Idea studio." subtitle="Capture first. Organize when you're ready." action={<button className="button-primary" onClick={()=>setEditingNote({id:uid(),title:'',body:'',tag:'Personal',updated:Date.now()})}><Plus size={17}/> New note</button>}/><div className="ideas-toolbar"><div className="input-search"><Search size={16}/><input value={notesSearch} onChange={e=>setNotesSearch(e.target.value)} placeholder="Search your ideas..."/></div><span className="muted-label">{notes.length} saved notes</span></div>{editingNote?<div className="panel note-editor"><div className="editor-top"><span className="panel-kicker">Note editor</span><button className="icon-button" onClick={()=>setEditingNote(null)}><X size={18}/></button></div><input className="note-title-input" value={editingNote.title} onChange={e=>setEditingNote(n=>n?{...n,title:e.target.value}:n)} placeholder="Give this idea a title..."/><div className="note-meta"><select value={editingNote.tag} onChange={e=>setEditingNote(n=>n?{...n,tag:e.target.value}:n)}><option>Personal</option><option>Product</option><option>Work</option><option>Learning</option><option>Someday</option></select><span>Autosave when you save</span></div><textarea className="note-body-input" value={editingNote.body} onChange={e=>setEditingNote(n=>n?{...n,body:e.target.value}:n)} placeholder="Let your thoughts flow..."/><div className="editor-actions"><button className="button-secondary" onClick={()=>setEditingNote(null)}>Cancel</button><button className="button-primary" onClick={()=>{if(!editingNote.title.trim()){notify('Give your note a title first');return;}setNotes(ns=>[ {...editingNote,updated:Date.now()},...ns.filter(n=>n.id!==editingNote.id)]);setEditingNote(null);notify('Note saved');}}>Save note <Check size={16}/></button></div></div>:<div className="notes-grid">{notes.filter(n=>(n.title+' '+n.body+' '+n.tag).toLowerCase().includes(notesSearch.toLowerCase())).map((n,i)=><button key={n.id} className={`note-card note-tone-${i%4}`} onClick={()=>setEditingNote(n)}><div className="note-card-top"><span className="note-tag">{n.tag}</span><MoreHorizontal size={17}/></div><h3>{n.title}</h3><p>{n.body}</p><div className="note-card-bottom"><span>{new Date(n.updated).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span><span className="note-open">Open <ArrowRight size={13}/></span></div><span className="note-delete" onClick={e=>{e.stopPropagation();setNotes(ns=>ns.filter(x=>x.id!==n.id));notify('Note deleted');}} title="Delete note"><Trash2 size={14}/></span></button>)}<button className="new-note-card" onClick={()=>setEditingNote({id:uid(),title:'',body:'',tag:'Personal',updated:Date.now()})}><span><Plus size={22}/></span><b>Capture a new thought</b><small>Start with a blank page</small></button></div>}</section>}

        {page==='Focus'&&<section className="page-enter focus-page"><PageTitle kicker="One thing at a time" title="Focus room." subtitle="A little less noise. A little more intention."/><div className="focus-room panel"><div className="focus-room-glow"/><div className="focus-mode-label"><span className="status-dot"/>{focusRunning?'Session in progress':'Ready when you are'}</div><div className="focus-timer-ring"><div><span>{formatTime(focusSeconds)}</span><small>{focusRunning?'Stay with it':'Focus session'}</small></div></div><div className="focus-lengths">{[15,25,45,60].map(m=><button key={m} className={focusLength===m?'selected':''} onClick={()=>{setFocusLength(m);if(!focusRunning)setFocusSeconds(m*60);}}>{m} min</button>)}</div><div className="focus-controls"><button className="button-primary" onClick={()=>{if(focusSeconds===0)setFocusSeconds(focusLength*60);setFocusRunning(v=>!v);}}>{focusRunning?<Pause size={17}/>:<Play size={17}/>} {focusRunning?'Pause session':'Begin focus'}</button><button className="button-secondary" onClick={()=>{setFocusRunning(false);setFocusSeconds(focusLength*60);}}>Reset</button></div><p className="focus-hint"><Headphones size={15}/> A little ambient sound can help you settle in.</p><button className="text-button" onClick={()=>changePage('Sleep Studio')}>Open sound studio <ArrowRight size={15}/></button></div></section>}

        {page==='Sleep Studio'&&<section className="page-enter sleep-page"><div className="sleep-hero"><div className="sleep-ambient-glow"/><div className="eyebrow"><MoonStar size={14}/> YOUR PERSONAL SOUND ENVIRONMENT</div><h1>Find your quiet<span>.</span></h1><p>Layer a few sounds. Lower the noise of the day.</p><div className="sleep-wave"><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/><span/></div><div className="sleep-main-controls"><button className="button-primary" onClick={()=>isPlaying?stopAudio():playMix()}>{isPlaying?<Pause size={17}/>:<Play size={17}/>} {isPlaying?'Pause all sounds':'Play soundscape'}</button><button className="button-secondary" onClick={stopAudio}><VolumeX size={16}/> Stop</button><button className="button-secondary" onClick={savePreset}><Plus size={16}/> Save mix</button></div></div><div className="sound-section-head"><div><div className="panel-kicker">Build your atmosphere</div><h2>Sound layers</h2></div><span className="muted-label">{activeSounds.length} active</span></div><div className="sound-grid">{(Object.keys(soundNames) as SoundKey[]).map(key=>{const Icon=iconForSound[key];return <div className={`sound-card ${activeSounds.includes(key)?'sound-active':''}`} key={key}><div className="sound-card-head"><span className={`sound-icon sound-${key}`}><Icon size={19}/></span><button className={`sound-toggle ${activeSounds.includes(key)?'on':''}`} onClick={()=>toggleSound(key)} aria-label={`${activeSounds.includes(key)?'Stop':'Play'} ${soundNames[key]}`}>{activeSounds.includes(key)?<Pause size={14}/>:<Play size={14}/>}</button></div><h3>{soundNames[key]}</h3><p>{({rain:'Soft rainfall against glass',thunder:'Low distant storm ambience',fire:'Gentle crackling warmth',forest:'A quiet world after dark',ocean:'Slow waves along the shore',noise:'A steady blanket of sound'} as Record<SoundKey,string>)[key]}</p><div className="sound-volume-row"><Volume2 size={15}/><input aria-label={`${soundNames[key]} volume`} type="range" min="0" max="100" value={sounds[key]} onChange={e=>updateSound(key,Number(e.target.value))}/><span>{sounds[key]}%</span></div></div>;})}</div><div className="sleep-bottom-grid"><div className="panel master-panel"><div className="panel-head"><div><div className="panel-kicker">Overall level</div><h3>Master volume</h3></div><Volume2 size={19}/></div><div className="master-slider"><input type="range" min="0" max="100" value={prefs.soundMaster} onChange={e=>setMaster(Number(e.target.value))}/><span>{prefs.soundMaster}%</span></div><p className="subtle-copy">Individual layers stay balanced relative to the overall level.</p></div><div className="panel timer-panel"><div className="panel-head"><div><div className="panel-kicker">Let the night take over</div><h3><AlarmClock size={17}/> Sleep timer</h3></div><span className="timer-status">{timerRunning?'Running':'Ready'}</span></div><div className="timer-select-row"><select value={prefs.timerMinutes} onChange={e=>setPref('timerMinutes',Number(e.target.value))}><option value={5}>5 minutes</option><option value={15}>15 minutes</option><option value={30}>30 minutes</option><option value={45}>45 minutes</option><option value={60}>60 minutes</option><option value={90}>90 minutes</option><option value={120}>2 hours</option></select><label>Fade out<select value={prefs.fadeMinutes} onChange={e=>setPref('fadeMinutes',Number(e.target.value))}><option value={0}>Off</option><option value={1}>1 min</option><option value={5}>5 min</option><option value={10}>10 min</option><option value={15}>15 min</option></select></label></div><div className="timer-display"><span>{timerRunning?formatTime(timerRemaining):`${prefs.timerMinutes}:00`}</span><small>{timerRunning?'Time remaining':'Planned duration'}</small></div><div className="timer-actions">{timerRunning?<button className="button-secondary" onClick={()=>{setTimerRunning(false);setTimerRemaining(0);}}>Cancel timer</button>:<button className="button-primary" onClick={setTimer}><Play size={15}/> Start sleep timer</button>}</div></div></div>{Object.keys(soundPreset).length>0&&<><div className="sound-section-head presets-head"><div><div className="panel-kicker">Your saved mixes</div><h2>Sound presets</h2></div></div><div className="preset-list">{Object.keys(soundPreset).map(name=><div className="preset-item" key={name}><span className="preset-icon"><AudioLines size={17}/></span><span>{name}</span><button className="button-secondary small" onClick={()=>loadPreset(name)}>Load</button><button className="icon-button danger-quiet" onClick={()=>setSoundPreset(p=>{const n={...p};delete n[name];return n;})}><Trash2 size={15}/></button></div>)}</div></>}</section>}

        {page==='Insights'&&<section className="page-enter"><PageTitle kicker="Notice your progress" title="A little perspective." subtitle="Progress is more than a perfect streak."/><div className="insights-grid"><StatCard icon={CheckCheck} label="Tasks completed" value={String(doneCount)} detail="Across your task list" /><StatCard icon={Target} label="Completion rate" value={`${progress}%`} detail="Of all saved tasks" /><StatCard icon={NotebookPen} label="Ideas captured" value={String(notes.length)} detail="Thoughts worth keeping" /><StatCard icon={AudioLines} label="Saved sound mixes" value={String(Object.keys(soundPreset).length)} detail="Your personal soundscapes" /></div><div className="panel insight-note"><span className="icon-chip violet"><Sparkles size={18}/></span><div><h3>Make progress your own.</h3><p>These numbers reflect your current saved data. Over time, this space can grow into weekly trends, focus history, and habit insights.</p></div></div><div className="section-heading"><div><div className="panel-kicker">A small win counts</div><h2>Recent tasks</h2></div><button className="text-button" onClick={()=>changePage('Tasks')}>View tasks <ArrowRight size={15}/></button></div><div className="panel task-panel">{tasks.filter(t=>t.done).slice(0,5).map(t=><TaskRow key={t.id} task={t} onToggle={toggleTask} onDelete={deleteTask}/>)}{!tasks.some(t=>t.done)&&<EmptyState title="Your first win is waiting." text="Complete a task to see it here."/>}</div></section>}

        {page==='Settings'&&<SettingsPage prefs={prefs} setPref={setPref} exportData={exportData} importData={importData} onToast={notify} onReset={()=>{if(window.confirm('Reset Dayflow settings to defaults? Your tasks and notes will be kept.')){setPrefs(defaultPrefs);notify('Settings reset to defaults');}}} onClear={()=>{if(window.confirm('Delete all tasks and notes from this browser? This cannot be undone.')){setTasks([]);setNotes([]);notify('Local tasks and notes cleared');}}}/>}
      </div>
      <footer className="app-footer"><span>dayflow<span className="accent-dot">.</span> <span className="footer-muted">A little clarity goes a long way.</span></span><span>Made for your flow <span className="footer-spark">✳</span></span></footer>
    </main>
    <nav className="tabbar" aria-label="Primary">{([['Home',Home],['Planner',CalendarDays]] as [Page,LucideIcon][]).map(([n,I])=><button key={n} className={`tab ${page===n?'active':''}`} onClick={()=>changePage(n)}><I size={21}/><span>{n}</span></button>)}<button className="tab-fab" aria-label="New task" onClick={()=>setShowAdd(true)}><Plus size={26}/></button><button className={`tab ${page==='Sleep Studio'?'active':''}`} onClick={()=>changePage('Sleep Studio')}><MoonStar size={21}/><span>Sleep</span></button><button className="tab" onClick={()=>setSidebarOpen(true)}><Menu size={21}/><span>More</span></button></nav>
    {isPlaying&&<div className="mini-player"><button className="mini-play" onClick={()=>isPlaying?stopAudio():playMix()}><Pause size={16}/></button><div className="mini-player-copy"><b>Your soundscape</b><span>{activeSounds.map(k=>soundNames[k]).join(' · ')||'Ambient sound'}</span></div><div className="mini-wave">{Array.from({length:14},(_,i)=><i key={i} style={{animationDelay:`${i*0.06}s`}}/>)}</div><button className="icon-button" title="Open Sleep Studio" onClick={()=>changePage('Sleep Studio')}><ArrowRight size={16}/></button><button className="icon-button" title="Stop audio" onClick={stopAudio}><X size={16}/></button></div>}
    {showAdd&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setShowAdd(false);}}><form className="task-modal" onSubmit={addTask}><div className="modal-heading"><div><div className="panel-kicker">Make it happen</div><h2>New task</h2></div><button type="button" className="icon-button" onClick={()=>setShowAdd(false)}><X size={18}/></button></div><label className="field-label">What needs doing?</label><input autoFocus className="text-input" value={taskTitle} onChange={e=>setTaskTitle(e.target.value)} placeholder="A small step, a big idea..." maxLength={180}/><div className="modal-fields"><label className="field-label">List<select value={taskList} onChange={e=>setTaskList(e.target.value)}><option>Personal</option><option>Projects</option><option>Work</option><option>Learning</option><option>Wellbeing</option></select></label><label className="field-label">Priority<select value={taskPriority} onChange={e=>setTaskPriority(e.target.value as Task['priority'])}><option>Low</option><option>Normal</option><option>High</option></select></label></div><div className="modal-footer"><span><kbd>Enter</kbd> to save</span><button type="button" className="button-secondary" onClick={()=>setShowAdd(false)}>Cancel</button><button className="button-primary" type="submit"><Plus size={16}/> Add task</button></div></form></div>}
    {commandOpen&&<div className="modal-backdrop command-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setCommandOpen(false);}}><div className="command-modal"><div className="command-search"><Search size={19}/><input autoFocus value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search tasks or jump to a page..."/><kbd>ESC</kbd></div><div className="command-label">Navigate</div>{pages.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())).map(p=><button className="command-row" key={p.name} onClick={()=>changePage(p.name)}><p.icon size={17}/><span>{p.name}</span><ArrowRight size={14}/></button>)}<div className="command-label">Quick actions</div><button className="command-row" onClick={()=>{setCommandOpen(false);setShowAdd(true);}}><Plus size={17}/><span>Create a new task</span><kbd>N</kbd></button><button className="command-row" onClick={()=>changePage('Sleep Studio')}><MoonStar size={17}/><span>Open Sleep Studio</span><ArrowRight size={14}/></button><div className="command-bottom"><span><Command size={13}/> DAYFLOW COMMAND PALETTE</span><span>Navigate faster</span></div></div></div>}
    {toast&&<div className="toast"><CheckCircle2 size={17}/>{toast}</div>}
  </div>;
}

function PageTitle({kicker,title,subtitle,action}:{kicker:string;title:string;subtitle:string;action?:React.ReactNode}){return <div className="page-title-row"><div><div className="eyebrow">{kicker}</div><h1>{title}</h1><p className="hero-subtitle">{subtitle}</p></div>{action}</div>}
function TaskRow({task,onToggle,onDelete}:{task:Task;onToggle:(id:string)=>void;onDelete:(id:string)=>void}){return <div className={`task-row ${task.done?'task-done':''}`}><button className={`task-check ${task.done?'checked':''}`} onClick={()=>onToggle(task.id)} aria-label={task.done?'Mark incomplete':'Complete task'}>{task.done&&<Check size={14}/>}</button><div className="task-row-copy"><span className="task-title">{task.title}</span><div className="task-meta"><span>{task.list}</span><span className="meta-separator">·</span><span className={`priority priority-${task.priority.toLowerCase()}`}><i/>{task.priority}</span></div></div><span className="task-due">{task.due===todayISO()?'Today':task.due}</span><button className="row-delete" onClick={()=>onDelete(task.id)} title="Delete task"><Trash2 size={15}/></button></div>}
function EmptyState({title,text,action,onClick}:{title:string;text:string;action?:string;onClick?:()=>void}){return <div className="empty-state"><span className="empty-icon"><CheckCheck size={23}/></span><h3>{title}</h3><p>{text}</p>{action&&<button className="button-secondary" onClick={onClick}><Plus size={15}/>{action}</button>}</div>}
function StatCard({icon:Icon,label,value,detail}:{icon:LucideIcon;label:string;value:string;detail:string}){return <div className="panel stat-card"><span className="icon-chip"><Icon size={18}/></span><span className="stat-label">{label}</span><strong>{value}</strong><small>{detail}</small></div>}
function Planner({tasks,onToggle,onDelete,onAdd,now}:{tasks:Task[];onToggle:(id:string)=>void;onDelete:(id:string)=>void;onAdd:()=>void;now:Date}){
 const [weekOffset,setWeekOffset]=useState(0);const start=new Date(now);const day=(start.getDay()+6)%7;start.setDate(start.getDate()-day+weekOffset*7);start.setHours(0,0,0,0);
 const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d;});
 const [selected,setSelected]=useState(todayISO());const selectedTasks=tasks.filter(t=>t.due===selected);
 return <section className="page-enter"><PageTitle kicker="Make a plan that breathes" title="Your planner." subtitle="A clearer view of the week ahead." action={<button className="button-primary" onClick={onAdd}><Plus size={17}/> Add task</button>}/><div className="planner-controls"><div><h2>{start.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><p>One week at a time.</p></div><div className="planner-arrows"><button className="icon-button" onClick={()=>setWeekOffset(v=>v-1)}><ChevronLeft size={18}/></button><button className="button-secondary small" onClick={()=>{setWeekOffset(0);setSelected(todayISO());}}>Today</button><button className="icon-button" onClick={()=>setWeekOffset(v=>v+1)}><ChevronRight size={18}/></button></div></div><div className="week-grid">{days.map(d=>{const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const dayTasks=tasks.filter(t=>t.due===iso);return <button key={iso} className={`week-day ${selected===iso?'day-selected':''} ${iso===todayISO()?'is-today':''}`} onClick={()=>setSelected(iso)}><span>{d.toLocaleDateString(undefined,{weekday:'short'}).toUpperCase()}</span><b>{d.getDate()}</b><small>{dayTasks.length} {dayTasks.length===1?'task':'tasks'}</small><i>{dayTasks.some(t=>!t.done)?'•':' '}</i></button>;})}</div><div className="section-heading planner-selected-head"><div><div className="panel-kicker">Your selected day</div><h2>{new Date(`${selected}T12:00:00`).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</h2></div><span className="muted-label">{selectedTasks.length} tasks</span></div><div className="panel task-panel">{selectedTasks.map(t=><TaskRow key={t.id} task={t} onToggle={onToggle} onDelete={onDelete}/>)}{selectedTasks.length===0&&<EmptyState title="A little open space." text="This day has no tasks yet. Add one when you're ready." action="Add task" onClick={onAdd}/>}</div><div className="planner-tip"><Sparkles size={17}/><span>Suggestion: leave a little breathing room between planned activities. Your day doesn't have to be packed to be meaningful.</span></div></section>
}
function SettingsPage({prefs,setPref,exportData,importData,onToast,onReset,onClear}:{prefs:Prefs;setPref:<K extends keyof Prefs>(key:K,value:Prefs[K])=>void;exportData:()=>void;importData:(e:React.ChangeEvent<HTMLInputElement>)=>void;onToast:(s:string)=>void;onReset:()=>void;onClear:()=>void}){
 const [section,setSection]=useState('Appearance');
 const groups=[{name:'Appearance',icon:Sun},{name:'Experience',icon:Sparkles},{name:'Dashboard',icon:Home},{name:'Tasks & planning',icon:ListTodo},{name:'Sound & sleep',icon:AudioLines},{name:'Data & privacy',icon:Download}];
 return <section className="page-enter"><PageTitle kicker="Make it feel like yours" title="Your settings." subtitle="A personal space should feel personal."/><div className="settings-layout"><aside className="settings-nav">{groups.map(g=><button key={g.name} className={section===g.name?'selected':''} onClick={()=>setSection(g.name)}><g.icon size={17}/>{g.name}<ChevronRight size={14}/></button>)}</aside><div className="settings-content">
 {section==='Appearance'&&<><SettingGroup title="Theme & color" description="Set the tone for your workspace."><SettingRow title="Appearance" desc="Choose a look or follow your system." control={<select value={prefs.theme} onChange={e=>setPref('theme',e.target.value as Prefs['theme'])}><option value="dark">Dark</option><option value="light">Light</option></select>}/><SettingRow title="Accent color" desc="The color used for highlights and progress." control={<div className="color-choices">{['#7c6cff','#3b82f6','#14b8a6','#ff8a5c','#ec4899','#1d2142'].map(c=><button key={c} className={`color-dot ${prefs.accent===c?'chosen':''}`} style={{background:c}} onClick={()=>setPref('accent',c)} aria-label={`Set accent ${c}`}/>)}</div>}/><SettingRow title="Compact layout" desc="Fit more content into the same space." control={<Toggle checked={prefs.compact} onChange={v=>setPref('compact',v)}/>} /></SettingGroup><SettingGroup title="Typography & time" description="Make details easier to scan."><SettingRow title="Clock format" desc="Choose your preferred time format." control={<select value={prefs.clock24?'24':'12'} onChange={e=>setPref('clock24',e.target.value==='24')}><option value="12">12-hour</option><option value="24">24-hour</option></select>}/><SettingRow title="Name for greetings" desc="Used in the dashboard greeting." control={<input className="setting-input" value={prefs.name} onChange={e=>setPref('name',e.target.value)} maxLength={32}/>} /></SettingGroup></>}
 {section==='Experience'&&<><SettingGroup title="Motion & welcome" description="Keep the experience calm or make it more expressive."><SettingRow title="Animated boot screen" desc="Show the logo reveal on your next fresh session." control={<Toggle checked={prefs.boot} onChange={v=>setPref('boot',v)}/>} /><SettingRow title="Motion effects" desc="Enable decorative movement and transitions." control={<Toggle checked={prefs.motion} onChange={v=>setPref('motion',v)}/>} /><SettingRow title="Personal greeting" desc="Show a time-aware welcome message." control={<Toggle checked={prefs.greeting} onChange={v=>setPref('greeting',v)}/>} /></SettingGroup><SettingGroup title="Accessibility" description="Your comfort comes first."><SettingRow title="Reduced motion" desc="Turn off most nonessential animation using Motion effects." control={<Toggle checked={!prefs.motion} onChange={v=>setPref('motion',!v)}/>} /><SettingRow title="Reset preferences" desc="Restore the default theme and experience settings." control={<button className="button-secondary small" onClick={onReset}>Reset defaults</button>}/></SettingGroup></>}
 {section==='Dashboard'&&<SettingGroup title="Dashboard widgets" description="Choose what appears when you open Dayflow."><SettingRow title="Live clock" desc="Show the time in the home greeting." control={<Toggle checked={prefs.showClock} onChange={v=>setPref('showClock',v)}/>} /><SettingRow title="Daily progress" desc="Show the progress summary card." control={<Toggle checked={prefs.showProgress} onChange={v=>setPref('showProgress',v)}/>} /><SettingRow title="Daily inspiration" desc="Show the small encouragement panel." control={<Toggle checked={prefs.showQuote} onChange={v=>setPref('showQuote',v)}/>} /><SettingRow title="Default page" desc="Choose where Dayflow opens." control={<select value={prefs.defaultPage} onChange={e=>setPref('defaultPage',e.target.value as Page)}>{pages.filter(p=>p.name!=='Settings').map(p=><option key={p.name}>{p.name}</option>)}</select>}/></SettingGroup>}
 {section==='Tasks & planning'&&<SettingGroup title="Planning preferences" description="Small defaults that make daily planning easier."><SettingRow title="Week starts on Monday" desc="Use a Monday-first planner week." control={<Toggle checked={prefs.weekStartsMonday} onChange={v=>setPref('weekStartsMonday',v)}/>} /><SettingRow title="Compact task rows" desc="Use a denser layout for task lists." control={<Toggle checked={prefs.compact} onChange={v=>setPref('compact',v)}/>} /><SettingRow title="Task data" desc="Export your tasks and notes as a backup." control={<button className="button-secondary small" onClick={exportData}>Export backup <Download size={14}/></button>}/></SettingGroup>}
 {section==='Sound & sleep'&&<><SettingGroup title="Sound defaults" description="Set a comfortable starting point for your soundscapes."><SettingRow title="Master volume" desc="Default overall sound level." control={<div className="setting-range"><input type="range" min="0" max="100" value={prefs.soundMaster} onChange={e=>setPref('soundMaster',Number(e.target.value))}/><span>{prefs.soundMaster}%</span></div>}/><SettingRow title="Default sleep timer" desc="Preselected duration in Sleep Studio." control={<select value={prefs.timerMinutes} onChange={e=>setPref('timerMinutes',Number(e.target.value))}><option value={15}>15 minutes</option><option value={30}>30 minutes</option><option value={45}>45 minutes</option><option value={60}>60 minutes</option><option value={90}>90 minutes</option><option value={120}>2 hours</option></select>}/><SettingRow title="Fade-out duration" desc="Desired fade duration near the end of a sleep timer." control={<select value={prefs.fadeMinutes} onChange={e=>setPref('fadeMinutes',Number(e.target.value))}><option value={0}>Off</option><option value={1}>1 minute</option><option value={5}>5 minutes</option><option value={10}>10 minutes</option><option value={15}>15 minutes</option></select>}/></SettingGroup><div className="settings-note"><MoonStar size={18}/><div><b>Audio note</b><p>Sounds are generated locally as synthetic ambience in this starter build. Replace or supplement them with licensed recordings for a richer final sound library.</p></div></div></>}
 {section==='Data & privacy'&&<><SettingGroup title="Your data" description="Your starter build stores information in this browser."><SettingRow title="Export a backup" desc="Download tasks, notes, preferences, and saved mixes." control={<button className="button-secondary small" onClick={exportData}><Download size={15}/> Export JSON</button>}/><SettingRow title="Import a backup" desc="Restore a previous Dayflow JSON backup." control={<label className="button-secondary small upload-label">Choose file<input type="file" accept="application/json,.json" onChange={importData} hidden/></label>}/><SettingRow title="Clear tasks and notes" desc="Remove local task and note data. Settings are retained." control={<button className="button-danger small" onClick={onClear}><Trash2 size={14}/> Clear data</button>}/></SettingGroup><div className="settings-note"><Activity size={18}/><div><b>Local-first by design</b><p>Data stays in this browser's local storage. This version does not have accounts or cloud sync. Export a backup before clearing browser data.</p></div></div></>}
 <div className="settings-save-note"><CheckCircle2 size={15}/> Your preferences save automatically on this device.</div>
 </div></div></section>;
}
function SettingGroup({title,description,children}:{title:string;description:string;children:React.ReactNode}){return <div className="panel setting-group"><div className="setting-group-head"><h3>{title}</h3><p>{description}</p></div>{children}</div>}
function SettingRow({title,desc,control}:{title:string;desc:string;control:React.ReactNode}){return <div className="setting-row"><div><b>{title}</b><p>{desc}</p></div><div className="setting-control">{control}</div></div>}
function Toggle({checked,onChange}:{checked:boolean;onChange:(v:boolean)=>void}){return <button className={`toggle ${checked?'toggle-on':''}`} role="switch" aria-checked={checked} onClick={()=>onChange(!checked)}><span/></button>}
